let t = 0.0;
let vel = 0.02;
let ghost;
let bird;
let pg;
let biquadFilter;
let num = 0;

function preload() {
    ghost = loadImage("file:///Users/unclerm/Vibe Coding/4K MV Visual Integration Editor/assets_cache/ghost.png");
    bird = loadImage("file:///Users/unclerm/Vibe Coding/4K MV Visual Integration Editor/assets_cache/bird.png");
}

function setup() {
    createCanvas(800, 800);
    angleMode(DEGREES);
    rectMode(CENTER);
    // texture: reference @sayama
    pg = createGraphics(width, height);
    pg.noStroke();
    for (let i = 0; i < 15000; i++) {
        let x = random(width);
        let y = random(height);
        let n = noise(x * 0.01, y * 0.01) * width * 0.002;
        pg.fill(255, 30);
        pg.rect(x, y, n, n);
    }
}

function draw() {
    randomSeed(0);
    background("#98c1d9");
    noStroke();

    let shadowCol = color('#95adbe');
    fill(shadowCol);
    for (let i = 0; i < 15; i++) {
        let w1 = randomGaussian(width * 1.8, width * 0.2);
        let h1 = height * random(0.05, 0.3);
        rect(0, random(height), w1, h1, abs(h1 / 2));
    }

    push();
    for (let i = 0; i < 15; i++) {
        push();
        let w = randomGaussian(width, width * 0.4);
        let h = width * random(0.05, 0.4);

        translate(0, random(height));
        let gradientFill = drawingContext.createLinearGradient(
            0,
            -h / 2,
            0,
            h / 2
        );

        stroke(51);
        push();
        gradientFill.addColorStop(0, color('#e0f0ea'));
        gradientFill.addColorStop(1, color('#95adbe'));
        drawingContext.fillStyle = gradientFill;
        rect(0, 0, w, h, abs(h / 2));

        drawingContext.clip();
        for (let i = 0; i < 800; i++) {
            fill(0);
            noStroke();
            ellipse(random(-w * 0.1, w / 2), randomGaussian(h / 2, h * 0.2), 1);
        }
        pop();

        for (let j = 0; j < w / 3; j += 60) {
            push();
            translate(j, -h * 0.2);
            rotate(10);
            stroke(51);
            ellipse(0, 0, h * 0.04, h * 0.06);
            pop();
        }
        pop();
    }
    pop();

    let floatOffset = sin(frameCount * 2) * 10;
    if (ghost) {
        push();
        scale(0.3);
        image(ghost, width * 2.3, height * 0.52 + floatOffset);
        pop();
    }
    if (bird) {
        push();
        scale(0.4);
        image(bird, width * 1.8, height * 1.8 - floatOffset);
        pop();
    }
    if (pg) {
        image(pg, 0, 0);
    }
}
